import type {
  CreateGuestInput,
  GuestRepository,
  LoggerPort,
  StoredGuest,
} from '@kalamkala/app-core'
import { guests } from '@kalamkala/db-schema'
import { eq } from 'drizzle-orm'

import type { AppDatabase } from './database.js'

export type D1GuestRepositoryOptions = {
  db: AppDatabase
  logger?: LoggerPort
}

type GuestRow = typeof guests.$inferSelect

/** Guest list rows; IDs and QR tokens are generated by the application. */
export class D1GuestRepository implements GuestRepository {
  private readonly db: AppDatabase
  private readonly logger: LoggerPort | undefined

  constructor(options: D1GuestRepositoryOptions) {
    this.db = options.db
    this.logger = options.logger
  }

  async findById(id: string): Promise<StoredGuest | null> {
    const row = await this.db.query.guests.findFirst({ where: eq(guests.id, id) })
    return row === undefined ? null : this.toStoredGuest(row)
  }

  async findByQrToken(qrToken: string): Promise<StoredGuest | null> {
    const row = await this.db.query.guests.findFirst({ where: eq(guests.qrToken, qrToken) })
    return row === undefined ? null : this.toStoredGuest(row)
  }

  async listByInvitation(invitationId: string): Promise<StoredGuest[]> {
    const rows = await this.db
      .select()
      .from(guests)
      .where(eq(guests.invitationId, invitationId))
    return rows.map((row) => this.toStoredGuest(row))
  }

  async create(input: CreateGuestInput): Promise<StoredGuest> {
    const rows = await this.db
      .insert(guests)
      .values({
        id: crypto.randomUUID(),
        invitationId: input.invitationId,
        name: input.name,
        phoneNormalized: input.phoneNormalized,
        category: input.category,
        allowedEventIdsJson: input.allowedEventIdsJson,
        maxPax: input.maxPax,
        tableNumber: input.tableNumber,
        sessionLabel: input.sessionLabel,
        qrToken: input.qrToken,
        waSentStatus: input.waSentStatus,
      })
      .returning()

    const row = rows[0]
    if (row === undefined) {
      throw new Error(`Failed to create guest for invitation ${input.invitationId}`)
    }
    return this.toStoredGuest(row)
  }

  async markWaSent(id: string, sentAt: Date): Promise<void> {
    const rows = await this.db
      .update(guests)
      .set({ waSentStatus: 'SENT', waSentAt: sentAt, updatedAt: new Date() })
      .where(eq(guests.id, id))
      .returning({ id: guests.id })

    if (rows[0] === undefined) {
      this.logger?.error('Guest not found while marking WhatsApp as sent', { guestId: id })
      throw new Error(`Guest ${id} not found`)
    }
  }

  private toStoredGuest(row: GuestRow): StoredGuest {
    return {
      id: row.id,
      invitationId: row.invitationId,
      name: row.name,
      phoneNormalized: row.phoneNormalized,
      category: row.category,
      allowedEventIdsJson: row.allowedEventIdsJson,
      maxPax: row.maxPax,
      tableNumber: row.tableNumber,
      sessionLabel: row.sessionLabel,
      qrToken: row.qrToken,
      waSentStatus: row.waSentStatus,
      waSentAt: row.waSentAt,
    }
  }
}
